inputs.script:
// Airtable automation setup
// Table: Content Channels (Alex Woung)
// Trigger: When record matches conditions
// Condition: Content Automation Action is not empty
// Input variable: recordId = Airtable record ID from the trigger

const {recordId} = input.config();
const OPUS_WEBHOOK_URL = 'https://n8n.dulcy.io/webhook/REDACTED_PATH';
const FRAME_WEBHOOK_URL = 'https://n8n.dulcy.io/webhook/REDACTED_PATH';
const DISTRIBUTION_WEBHOOK_URL = 'https://n8n.dulcy.io/webhook/REDACTED_PATH';
const table = base.getTable('Content Channels (Alex Woung)');

if (!recordId || !String(recordId).startsWith('rec')) {
    throw new Error('A valid content recordId is required.');
}

const record = await table.selectRecordAsync(recordId);
if (!record) throw new Error(`Content record ${recordId} was not found.`);

const action = record.getCellValueAsString('Content Automation Action').trim();
const allowed = new Set([
    'Sync Frame.io',
    'Submit to OpusClip',
    'Refresh Opus Clips',
    'Generate Distribution Pack',
]);
if (!allowed.has(action)) {
    output.set('started', false);
    output.set('ignored', true);
    output.set('message', 'No supported Content OS action was selected.');
    return;
}

const webhookUrl = action === 'Sync Frame.io'
    ? FRAME_WEBHOOK_URL
    : action === 'Generate Distribution Pack'
        ? DISTRIBUTION_WEBHOOK_URL
        : OPUS_WEBHOOK_URL;
const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({recordId, action}),
});

const responseText = await response.text();
if (!response.ok) {
    throw new Error(`Content OS returned HTTP ${response.status}: ${responseText || 'No response body'}`);
}

// Clear only after n8n accepted the request, allowing a deliberate retry later.
await table.updateRecordAsync(recordId, {
    'Content Automation Action': null,
});

output.set('started', true);
output.set('recordId', recordId);
output.set('action', action);
output.set('n8nResponse', responseText || 'Accepted');
